package com.cyberguard.model;

import java.time.LocalDateTime;

/**
 * Model representing a defensive security alert generated by threat detection rules.
 */
public class Alert {
    private int id;
    private String ipAddress;
    private String threatType;
    private String severity;       // HIGH (Red), MEDIUM (Yellow), LOW (Blue)
    private LocalDateTime detectionTime;
    private String status;         // ACTIVE, UNDER_INVESTIGATION, RESOLVED
    private String description;
    private String resolvedBy;
    private LocalDateTime resolvedAt;

    public Alert() {
    }

    public Alert(int id, String ipAddress, String threatType, String severity,
                 LocalDateTime detectionTime, String status, String description) {
        this.id = id;
        this.ipAddress = ipAddress;
        this.threatType = threatType;
        this.severity = severity;
        this.detectionTime = detectionTime;
        this.status = status;
        this.description = description;
    }

    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getIpAddress() {
        return ipAddress;
    }

    public void setIpAddress(String ipAddress) {
        this.ipAddress = ipAddress;
    }

    public String getThreatType() {
        return threatType;
    }

    public void setThreatType(String threatType) {
        this.threatType = threatType;
    }

    public String getSeverity() {
        return severity;
    }

    public void setSeverity(String severity) {
        this.severity = severity;
    }

    public LocalDateTime getDetectionTime() {
        return detectionTime;
    }

    public void setDetectionTime(LocalDateTime detectionTime) {
        this.detectionTime = detectionTime;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public String getResolvedBy() {
        return resolvedBy;
    }

    public void setResolvedBy(String resolvedBy) {
        this.resolvedBy = resolvedBy;
    }

    public LocalDateTime getResolvedAt() {
        return resolvedAt;
    }

    public void setResolvedAt(LocalDateTime resolvedAt) {
        this.resolvedAt = resolvedAt;
    }
}
